package com.example.goober;

import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.net.Uri;import android.widget.*;
public class MainActivity extends Activity { public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);findViewById(R.id.chat).setOnClickListener(v->startActivity(new Intent(this,ChatActivity.class)));findViewById(R.id.settings).setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));findViewById(R.id.overlay).setOnClickListener(v->{if(Build.VERSION.SDK_INT>=23&&!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));else startService(new Intent(this,FloatingGooberService.class));});findViewById(R.id.notifications).setOnClickListener(v->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS")));findViewById(R.id.youtube).setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.youtube.com/"));startActivity(i);});}}
